# Transport of the reviewed navigation diff; no branch update or gameplay bypass.
import base64,gzip,hashlib,json,subprocess
from pathlib import Path
m={'patch':'2fa46b635b3bbb552d72a1e23d2f3aac763d42dd063cf7dac6bd493dc8adbb05','files':[{'path':'src/game/mosaicCityRuntime.js','before':'17f08e7c3c9c6304efdbe41e1f346ff235da34d809dec7c9b2600932c7d2741b','after':'f9b920e281bb2aaca67e929271a630cb3677000fd8bfa8fbba2e7cbf1fade170'},{'path':'scripts/mosaicResidentNavigation.test.mjs','before':None,'after':'fb1c8c0f3a5ec463ccc1a35a5474776e695f23c7ee0ee87668c9eea5c9e6c03f'},{'path':'.github/workflows/residents-viewmodels.yml','before':'928c276665ce6e5074c8b7425609589be5869c2ef32564958202a336b013cdbc','after':'efc78b5da432649e31633215f4d4bae3469990ffaf94f287586ee8e162b583bf'}]}
encoded=''
for f in m['files']:
 p=Path(f['path']);assert not p.is_symlink()
 assert (hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None)==f['before'],f['path']
patch=gzip.decompress(base64.b64decode(encoded));assert hashlib.sha256(patch).hexdigest()==m['patch']
Path('/tmp/navigation.patch').write_bytes(patch)
subprocess.run(['git','apply','--check','/tmp/navigation.patch'],check=True)
subprocess.run(['git','apply','/tmp/navigation.patch'],check=True)
p=Path('/tmp/ec-verified/manifest.json');manifest=json.loads(p.read_text())
for f in m['files']:
 assert hashlib.sha256(Path(f['path']).read_bytes()).hexdigest()==f['after'],f['path']
 prior=next((item for item in manifest['files'] if item['path']==f['path']),None)
 if prior:prior['after']=f['after']
 else:manifest['files'].append(f)
p.write_text(json.dumps(manifest,indent=2))
